import XCTest
import KwipMLCore
@testable import KwipMLApp
final class ObjectiveExplicitCaptureTests:XCTestCase {
 private struct Fixture:Decodable {let policy:TrainingSampleCapturePolicy;let recipe:JSONValue;let mapping:LossTargetMapping;let graph:GraphDocument;let manifest:[String:JSONValue];let event:[String:JSONValue];let predictionData:Data;let activationData:Data;let epoch:JSONValue}
 private func fixtures()throws->[Fixture] {try JSONDecoder().decode([Fixture].self,from:Data(base64Encoded:snapshot)!)}
 private func context(_ f:Fixture,explicit:Bool=true)throws->WorkflowObjectiveArtifactContext {
  try .init(recipe:LossRecipe(configuration:LossConfiguration.decodeRecipe(f.recipe),source:.init(domain:.control,localID:"objective"),targetMapping:f.mapping),runID:f.manifest["runID"]!.stringValue!,inputContract:TypedTensorContract(sample:[2],dtype:.float32),outputSampleShape:[2],trainingCount:48,evaluationCount:16,expectedEpochs:1,scalarization:.mean,device:.cpu,policy:f.policy,explicitSampleCapture:explicit)
 }
 private func mutate(_ value:JSONValue,path:[String],replacement:JSONValue)->JSONValue {guard let first=path.first else{return replacement};if case .object(var o)=value{o[first]=mutate(o[first] ?? .null,path:Array(path.dropFirst()),replacement:replacement);return .object(o)};return value}
 func testActualSchemaTwoAcrossFourPermissionsKeepsSavedAndLiveTypedRowsEqual()throws {
  let registry=try ComponentRegistry.builtIn()
  for f in try fixtures().prefix(4) {
   let c=try context(f),saved=try WorkflowObjectiveArtifacts.predictions(f.predictionData,metadata:f.manifest["predictionPreview"]!,context:c)
   let live=try XCTUnwrap(WorkflowModelTrainingExecution.objectivePresentation(event:f.event,context:c))
   XCTAssertEqual(saved,live);XCTAssertEqual(saved.rows.count,f.policy.predictionRows ? 16:0)
   XCTAssertNoThrow(try WorkflowModelTrainingExecution.verifyPresentation(event:f.event,graph:f.graph,sampleCapture:f.policy,objectiveContext:c,capturedRegistry:registry))
   XCTAssertNoThrow(try WorkflowActivationArtifact.decode(f.activationData,metadata:f.manifest["activationPreview"]!,runID:c.runID,graphHash:f.manifest["graphHash"]!.stringValue!,graph:f.graph,sampleCapture:f.policy,objectiveContext:c,capturedRegistry:registry))
   XCTAssertThrowsError(try WorkflowObjectiveArtifacts.predictions(f.predictionData,metadata:f.manifest["predictionPreview"]!,context:context(f,explicit:false)))
  }
 }
 func testRealNamedRoutingRequiresCapturedRegistryAndKeepsEachOutputOrigin()throws {
  let f=try fixtures().last!,c=try context(f),registry=try ComponentRegistry.builtIn()
  let origins=Dictionary(uniqueKeysWithValues:f.graph.nodes.map {($0.id,CompositeNodeOrigin(instancePath:[],localNodeID:$0.id,definition:nil))})
  let captures=try WorkflowVerifiedModelCaptures(event:f.event,graph:f.graph,origins:origins,sampleCapture:f.policy,objectiveContext:c,capturedRegistry:registry)
  let ports=try XCTUnwrap(captures.ports(instancePath:[],localNodeID:"routing"))
  XCTAssertEqual(Set(ports.keys),["part0","part1","part2"])
  XCTAssertNil(ports["out"])
  XCTAssertThrowsError(try WorkflowModelTrainingExecution.verifyPresentation(event:f.event,graph:f.graph,sampleCapture:f.policy,objectiveContext:c))
  var missing=registry;missing.components.removeAll {$0.id == "split"}
  XCTAssertThrowsError(try WorkflowModelTrainingExecution.verifyPresentation(event:f.event,graph:f.graph,sampleCapture:f.policy,objectiveContext:c,capturedRegistry:missing))
 }
 func testRepinnedSchemaStatusAndLiveLegacyLabelTamperingRefuses()throws {
  let f=try fixtures()[3],c=try context(f),registry=try ComponentRegistry.builtIn()
  var p=try JSONDecoder().decode([String:JSONValue].self,from:f.predictionData)
  for (key,value) in [("schemaVersion",JSONValue.integer(1)),("captureStatus",.string("omittedByPolicy"))] {
   var bad=p;bad[key]=value;let data=try JSONEncoder().encode(bad)
   let pin:JSONValue = .object(["schemaVersion":bad["schemaVersion"]!,"file":.string("predictions.json"),"bytes":.integer(Int64(data.count)),"sha256":.string(WorkflowPhaseArtifacts.hash(data))])
   XCTAssertThrowsError(try WorkflowObjectiveArtifacts.predictions(data,metadata:pin,context:c))
  }
  p.removeValue(forKey:"captureStatus")
  let data=try JSONEncoder().encode(p),pin:JSONValue = .object(["schemaVersion":2,"file":.string("predictions.json"),"bytes":.integer(Int64(data.count)),"sha256":.string(WorkflowPhaseArtifacts.hash(data))])
  XCTAssertThrowsError(try WorkflowObjectiveArtifacts.predictions(data,metadata:pin,context:c))
  var bad=f.event;bad["predictions"] = .array([.object(["label":0,"predicted":0])])
  XCTAssertThrowsError(try WorkflowModelTrainingExecution.verifyPresentation(event:bad,graph:f.graph,sampleCapture:f.policy,objectiveContext:c,capturedRegistry:registry))
  bad=f.event;bad["accuracy"] = .number(0)
  XCTAssertThrowsError(try WorkflowModelTrainingExecution.objectivePresentation(event:bad,context:c))
  bad=f.event;bad["previews"]=mutate(bad["previews"]!,path:["head","shape"],replacement:.array([8,1]))
  XCTAssertThrowsError(try WorkflowModelTrainingExecution.verifyPresentation(event:bad,graph:f.graph,sampleCapture:f.policy,objectiveContext:c,capturedRegistry:registry))
 }
 func testSingleEpochUsesSameStrictObjectiveGeometryAndSequence()throws {
  let f=try fixtures()[3],c=try context(f)
  let epoch=try WorkflowObjectiveArtifacts.epoch(f.epoch,expectedEpoch:1,context:c)
  XCTAssertEqual(epoch.epoch,1);XCTAssertNil(epoch.accuracy)
  XCTAssertThrowsError(try WorkflowObjectiveArtifacts.epoch(f.epoch,expectedEpoch:2,context:c))
  XCTAssertThrowsError(try WorkflowObjectiveArtifacts.epoch(mutate(f.epoch,path:["objective","validation","rawShape"],replacement:.array([16,1])),expectedEpoch:1,context:c))
  XCTAssertThrowsError(try WorkflowObjectiveArtifacts.epoch(mutate(f.epoch,path:["accuracy"],replacement:.number(0)),expectedEpoch:1,context:c))
 }
 private struct LegacyFactory:Decodable {let recipe:JSONValue;let mapping:LossTargetMapping;let graph:GraphDocument;let metadata:JSONValue;let runID:String;let graphHash:String;let inputShape:[Int];let outputShape:[Int];let activationData:Data}
 func testAllEightActualFactoryActivationsUseObjectiveGraphContext()throws {
  let factories=try JSONDecoder().decode([LegacyFactory].self,from:Data(base64Encoded:legacyFactories)!),registry=try ComponentRegistry.builtIn()
  XCTAssertEqual(factories.count,8)
  for f in factories {
   let recipe=try LossRecipe(configuration:LossConfiguration.decodeRecipe(f.recipe),source:.init(domain:.control,localID:"objective"),targetMapping:f.mapping)
   let context=try WorkflowObjectiveArtifactContext(recipe:recipe,runID:f.runID,inputContract:TypedTensorContract(sample:f.inputShape,dtype:.float32),outputSampleShape:f.outputShape,trainingCount:48,evaluationCount:16,expectedEpochs:3,scalarization:.mean,device:.cpu,policy:.factory)
   XCTAssertNoThrow(try WorkflowActivationArtifact.decode(f.activationData,metadata:f.metadata,runID:f.runID,graphHash:f.graphHash,graph:f.graph,sampleCapture:nil,objectiveContext:context,capturedRegistry:registry),recipe.configuration.componentID)
  }
 }
 private let legacyFactories=""
 private let snapshot=""
}
